	UI_VIRUS_APPLY_VIRUS_SET: '设置默认病毒库',
	UI_VIRUS_CLAMAV_DETAIL: 'ClamAV是一款开源的病毒扫描引擎，是一个全球性的开源项目，由世界各地的开发者共同维护和贡献。自其诞生以来，ClamAV凭借其强大的检测能力和持续更新的病毒库，在信息安全领域赢得了广泛的认可。通过多年的不断优化和研发，ClamAV积累了丰富的病毒识别技术和经验，成为了众多用户信赖的病毒扫描解决方案。该项目的核心产品——ClamAV病毒扫描软件，以其高效、准确和轻量级的特点，被众多独立评测机构及安全专家誉为值得推荐的病毒防护工具。',
	UI_VIRUS_KAV_DETAIL: '卡巴斯基反病毒SDK（Kaspersky Anti-Virus SDK）是卡巴斯基实验室提供的专业级恶意代码检测解决方案，采用先进的SafeStream扫描引擎和实时更新的全球威胁情报库，能够精准识别病毒、木马、勒索软件等各类恶意程序，具有检测率高、误报率低的技术优势。该SDK支持跨平台部署（包括x86、ARM和MIPS架构），提供轻量级API接口，可快速集成到网络设备、安全网关及企业安全系统中，为各类硬件设备和软件解决方案提供企业级的安全防护能力。',
